# ---------- Data preparation ----------
DATA["Semester"] = DATA["Semester"].astype(int)
DATA["Marks"] = pd.to_numeric(DATA["Marks"], errors="coerce")
DATA["Attendance_Percent"] = pd.to_numeric(DATA["Attendance_Percent"], errors="coerce")

def student_semester_summary(rows):
    if rows.empty:
        return pd.DataFrame(columns=[
            "Student_ID","Student_Name","Department","Semester",
            "Average","Attendance","Status"
        ])

    g = rows.groupby(
        ["Student_ID", "Student_Name", "Department", "Semester"],
        as_index=False
    ).agg(
        Average=("Marks", "mean"),
        Attendance=("Attendance_Percent", "mean")
    )

    def status(x):
        if x < 50:
            return "Weak"
        elif x < 60:
            return "At Risk"
        return "Stable"

    g["Status"] = g["Average"].apply(status)
    return g

def get_filtered_data():
    rows = DATA.copy()

    department = department_var.get()
    semester = semester_var.get()
    status = status_var.get()

    if department != "All Departments":
        rows = rows[rows["Department"] == department]

    if semester != "Both Semesters":
        rows = rows[rows["Semester"] == int(semester[-1])]

    if status != "All Students":
        summary = student_semester_summary(rows)
        allowed = summary[summary["Status"] == status]
        keys = set(zip(allowed["Student_ID"], allowed["Semester"]))

        rows = rows[
            rows.apply(
                lambda r: (r["Student_ID"], r["Semester"]) in keys,
                axis=1
            )
        ]

    return rows

