# ---------- Dashboard update ----------
def update_dashboard(*args):
    rows = get_filtered_data()
    summary = student_semester_summary(rows)

    unique_students = rows["Student_ID"].nunique() if not rows.empty else 0
    average = rows["Marks"].mean() if not rows.empty else 0
    pass_count = (rows["Result"].astype(str).str.lower() == "pass").sum() if not rows.empty else 0
    fail_count = (rows["Result"].astype(str).str.lower() == "fail").sum() if not rows.empty else 0
    pass_rate = (pass_count / len(rows) * 100) if len(rows) else 0
    weak_count = (summary["Status"] == "Weak").sum()

    kpi_vars[0].set(f"{unique_students:,}")
    kpi_vars[1].set(f"{average:.2f}")
    kpi_vars[2].set(f"{pass_rate:.2f}%")
    kpi_vars[3].set(f"{weak_count:,}")

    # Semester graph
    ax.clear()
    semester_values = []
    labels = []

    for s in [1, 2]:
        part = rows[rows["Semester"] == s]
        if not part.empty:
            semester_values.append(part["Marks"].mean())
            labels.append(f"Semester {s}")

    if semester_values:
        ax.bar(labels, semester_values)
        ax.set_ylim(0, 100)
        ax.set_ylabel("Average Marks")
        ax.set_title("Average Performance")
        ax.grid(axis="y", alpha=0.2)

        for i, v in enumerate(semester_values):
            ax.text(i, v + 2, f"{v:.2f}", ha="center", fontweight="bold")
    else:
        ax.text(.5, .5, "No data", ha="center", va="center")

    fig.tight_layout()
    canvas.draw()

    # Grade distribution
    grade_ax.clear()
    grades = ["A", "B", "C", "D", "F"]
    counts = [int((rows["Grade"] == g).sum()) for g in grades]

    grade_ax.bar(grades, counts)
    grade_ax.set_title("Grades in Selected Data")
    grade_ax.set_ylabel("Records")
    grade_ax.grid(axis="y", alpha=0.2)

    for i, v in enumerate(counts):
        grade_ax.text(i, v + max(counts + [1]) * .02, str(v),
                      ha="center", fontweight="bold")

    grade_fig.tight_layout()
    grade_canvas.draw()

    # Stats
    stats_text.config(state="normal")
    stats_text.delete("1.0", "end")

    department = department_var.get()
    semester = semester_var.get()

    stats_text.insert("end", f"Selected Department: {department}\n")
    stats_text.insert("end", f"Selected Semester: {semester}\n\n")
    stats_text.insert("end", f"Pass Records: {pass_count:,}\n")
    stats_text.insert("end", f"Fail Records: {fail_count:,}\n")
    stats_text.insert("end", f"Pass Rate: {pass_rate:.2f}%\n\n")

    stats_text.insert("end", "Department Average:\n")
    for d in sorted(rows["Department"].dropna().unique()):
        part = rows[rows["Department"] == d]
        stats_text.insert("end", f"  • {d}: {part['Marks'].mean():.2f}\n")

    stats_text.insert("end", "\nProposed Outcome:\n")
    stats_text.insert(
        "end",
        f"Identify {weak_count} weak student-semester cases and use "
        "attendance, assignments and internal marks for targeted improvement."
    )
    stats_text.config(state="disabled")

    # Risk table
    for item in tree.get_children():
        tree.delete(item)

    risk = summary.sort_values("Average").head(20)

    for _, r in risk.iterrows():
        tree.insert(
            "",
            "end",
            values=(
                r["Student_ID"],
                r["Student_Name"],
                r["Department"],
                int(r["Semester"]),
                f"{r['Average']:.2f}",
                f"{r['Attendance']:.1f}%",
                r["Status"]
            )
        )

# Filters update immediately
department_box.bind("<<ComboboxSelected>>", update_dashboard)
semester_box.bind("<<ComboboxSelected>>", update_dashboard)
status_box.bind("<<ComboboxSelected>>", update_dashboard)

update_dashboard()

root.mainloop()
